-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Unit Weight from cells/IMPORT Unit Weight.csv in the folder of input cells. Two rows for one cell add up.
INSERT INTO "IMPORT Unit Weight" ("SKU", v, ver, is_deleted) SELECT coalesce(k0."SKU", throwIf(isNull(k0."SKU"), 'cells name a member SKU does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/IMPORT Unit Weight.csv', 'CSVWithNames', '"SKU" String, "value" String') c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU"
GROUP BY ALL;
